UPDATE articulos a SET contenido=(SELECT string_agg(coalesce(v.texto,substring(a.contenido from v.inicio for v.largo)),'' ORDER BY v.orden) FROM (VALUES (0, 1, 50, NULL::text),(1,0,0,E'<thead><tr><th scope="col">Condición de aceptación del sistema o componente mecánico</th><th scope="col">Cumple</th><th scope="col">No cumple</th><th scope="col">N/A*</th></tr></thead>'),(2, 51, 7, NULL::text),(3, 179, 28, NULL::text),(4,0,0,E'<td colspan="3">'),(5, 211, 1019, NULL::text),(6,0,0,E'e) Las pastas de balatas adheridas deben tener un grosor igual o mayor a 1.6 mm (1/16").'),(7, 1323, 45, NULL::text),(8,0,0,E'f) Las pastas de balata remachadas deben tener un grosor igual o mayor a 3.2 mm (1/8") o la superficie debe estar menos desgastada que las dimensiones especificadas por el fabricante del vehículo y en ningún caso la medida será menor a 0.8 mm (1/32") a la cabeza del remache.'),(9, 1653, 430, NULL::text)) v(orden,inicio,largo,texto)) WHERE a.id='f476f073-79b7-568a-972b-aca49b786318' AND md5(a.contenido)='ab793862890e9caa0f080bf47d6c240c' RETURNING a.id,md5(a.contenido) hash;